def get_conn() -> sqlite3.Connection:
    """获取当前线程的 SQLite 连接（懒初始化，线程安全）。"""
    if not hasattr(_thread_local, 'conn'):
        Path(settings.db_path).parent.mkdir(parents=True, exist_ok=True)
        conn = sqlite3.connect(settings.db_path, check_same_thread=False, timeout=30)
        conn.row_factory = sqlite3.Row
        conn.execute('PRAGMA journal_mode=WAL;')
        conn.execute('PRAGMA busy_timeout=30000;')
        _thread_local.conn = conn
    return _thread_local.conn

@contextmanager
def transaction() -> sqlite3.Connection:
    """事务上下文：正常提交，异常回滚。"""
    conn = get_conn()
    try:
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise

def init_db() -> None:
    """建表 + 索引 + 旧库迁移；应用启动时调用一次。"""
    if settings.database_url:
        from backend.storage import db_async as _dba
        _run_async(_dba.init_db_async())
        # dispose 引擎：_run_async 里的临时事件循环已关闭，asyncpg 连接已死，
        # 若不清缓存，后续 lifespan 里的 await init_db_async() 会拿到死连接。
        _run_async(_dba._dispose_engine())
    conn = get_conn()
    conn.executescript(_SCHEMA)
    conn.executescript(_INDEXES)
    for table, col, ddl in _ALTERS:
        cols = {row[1] for row in conn.execute(f'PRAGMA table_info({table})')}
        if col not in cols:
            try:
                conn.execute(ddl)
            except sqlite3.OperationalError as exc:
                logger.warning('迁移跳过 %s.%s: %s', table, col, exc)
    try:
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_users_phone ON users(phone) WHERE phone IS NOT NULL AND phone != ''")
    except sqlite3.OperationalError as exc:
        logger.warning('users.phone 唯一索引创建失败（存量重复数据），降级为普通索引: %s', exc)
        conn.execute("CREATE INDEX IF NOT EXISTS idx_users_phone ON users(phone) WHERE phone IS NOT NULL AND phone != ''")
    try:
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_card_token ON orders(card_token) WHERE card_token IS NOT NULL AND card_token != ''")
    except sqlite3.OperationalError:
        pass
    conn.commit()
    try:
        from backend.storage import catalog
        from backend.storage import db_async as _dba
        if _dba.dialect() == 'postgresql':
            # PG 模式下必须按 PG 目录数据判断是否 seed：sqlite 兜底库可能有历史
            # 数据，按 sqlite 计数判断会误跳过 PG 的种子灌入。
            needs_seed = not _run_async(catalog.catalog_ready())
        else:
            needs_seed = conn.execute('SELECT COUNT(*) FROM plans').fetchone()[0] == 0
        if needs_seed:
            _run_async(catalog.seed_catalog())
    except Exception:
        logger.warning('目录种子数据灌入失败（不影响记忆/交易表）', exc_info=True)
    logger.info('长期记忆数据库就绪: %s', settings.db_path)
